import numpy as np, torch, model
neg=model.negatives(); net=model.load()
torch.manual_seed(0)
cs=np.linspace(0,0.999,21); A=neg['a']
r1=[];rr={0.5:[],1.0:[],1.5:[]}
for c in cs:
    xi=torch.randn(1024,2); cc=torch.full((1024,),float(c))
    a=model.decode(net,xi,cc); a=np.asarray(a[0] if isinstance(a,tuple) else a)
    m=np.zeros(1024,bool)
    for i in range(4): m|=np.asarray(model.in_basin(i,a)).astype(bool)
    d=np.min(np.linalg.norm(a[:,None]-A[None],axis=2),1)
    r1.append(m.mean())
    for k in rr: rr[k].append((d<k).mean())
print('basin',' '.join(f'{x:.2f}' for x in r1), np.mean(r1))
for k in rr: print('near',k,' '.join(f'{x:.2f}' for x in rr[k]), np.mean(rr[k]))

